"""Acknowledge feedback without selling, debating or escalating ordinary criticism."""

import re
from catalog import normalize
from customer_phrasing import canonical

APOLOGY = "Дуже перепрошую за незручності. Ми покращуємося щодня. Дякую за відгук."


def feedback_kind(raw, context=None):
    text = canonical(raw)
    action = bool(re.search(r"поверніть|верните|хочу.{0,20}(?:повернут|вернут|обмін|обмен)|як.{0,15}повернут|как.{0,15}вернут|прошу.{0,20}(?:повер|обмін)|відшкоду|возмест|refund|не\s+той\s+товар|не\s+тот\s+товар|пошкоджен|поврежден|дірк|дырк|порван|бракован|не\s+(?:прийш|приш[её]л|достав)", text))
    negative = bool(re.search(r"г[аоі]вн|гімн|гамн|х[еє]рн|фігн|фигн|жах|ужас|кошмар|не\s+сподоб|не\s+подоб|не\s+понрав|розчар|разочар|поган\w*\s+(?:якіст|товар|бот|сервіс)|плох\w*\s+(?:качеств|товар|бот|сервис)|якіст\w*.{0,15}поган|качеств\w*.{0,15}плох|неякісн|некачествен|дурн\w*\s+бот|туп\w*\s+бот|бот.{0,15}(?:туп|дурн|дебіл|дебил)|зауважен|замечани|незадовол|недовол|жахливо|безтолк|повна\s+синтетик|полная\s+синтетик|обман|скарг|жалоб", text))
    positive = bool(re.search(r"сподобал|понравил|задоволен|задоволена|доволен|довольна|якіст\w*.{0,20}(?:супер|клас|чудов|гарн|добра|відмін)|качеств\w*.{0,20}(?:супер|класс|хорош|отлич)|(?:товар|штани|штанці|футболка|бот|сервіс|сервис).{0,20}(?:супер|клас|чудов|гарн|вогонь|бомба|огонь|отлич|круто)|(?:класн|гарн|чудов|офіген|офиген|отличн|крут)\w*\s+(?:штани|штанці|футболк|товар|сервіс|бот)|(?:забрав|отримав|получил|забрала|отримала|получила).{0,40}(?:супер|клас|чудов|гарн|вогонь|відмін|сподоб|понрав|круто)|рекомендую\s+(?:вас|магазин|продавця|продавца)", text))
    generic_positive = bool(re.search(r'\b(?:все|усе|всё)\s+(?:супер|клас|круто|чудово|гуд|ч[іе]тко)\b', text))
    positive |= bool(re.search(r'(?:якіст|якісь|качеств)\w*.{0,20}(?:бомба|вогонь|огонь)|'
                               r'(?:забрав|отримав|получил|забрала|отримала|получила).{0,45}(?:підійш|подошл|гарно\s+сіли|хорошо\s+сели)', text))
    negative |= bool(re.search(r'заскам|кидалов', text))
    negative |= bool(re.fullmatch(r'(?:(?:ти|ви|ты|вы|цей\s+бот|бот)\s+)?(?:лох|тупий|тупой|дурень|дурак|дебіл|дебил|ідіот|идиот)[!., ]*', text))
    action |= bool(re.search(r'(?:не\s+ті|не\s+той|не\s+та|не\s+тот|не\s+того).{0,12}(?:штани|футбол|товар|розмір|размер|колір|цвет)|'
                             r'(?:нитк|шов|шви|швы).{0,30}(?:розійш|разош|розліз|разлез)|'
                             r'(?:чому|почему).{0,25}(?:надіслал|прислал|відправил|отправил).{0,25}(?:чорн|черн|біл|бел|сір|сер)', text))
    pending_choice = (context or {}).get('awaiting') in ('order_confirmation','checkout','shipping_details') or (context or {}).get('checkout_stage') == 'details'
    positive = positive or generic_positive and not pending_choice
    return "action" if action else "negative" if negative else "positive" if positive else None
